-- TERRITORY: ADDITIVE 25-MASTERWORK CATALOG PATCH for CURRENT LIVE r2, 12.11.2026.
-- Run only after review, when live release is r2 enabled and 72 legacy recipes
-- exactly match committed stage8-r2-live-identity.json. DO NOT run the full
-- staged territory_profession_stage8_backend.sql against production.
-- This script does not modify ANY players, wallets, old item rows or receipts.
-- Older r2 clients keep working. New r4 client requires the handshake below.
BEGIN;
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '30s';

DO $guard$
DECLARE v_version text; v_enabled boolean; v_count integer; v_old_items bigint;
BEGIN
 SELECT version,enabled INTO v_version,v_enabled
 FROM public.territory_profession_stage8_release WHERE id=1 FOR UPDATE;
 IF NOT FOUND OR v_version <> 'profession-stage8-draft-20261025-r2' OR v_enabled IS DISTINCT FROM true
 THEN RAISE EXCEPTION 'masterwork_requires_active_live_r2'; END IF;
 SELECT count(*) INTO v_count FROM public.territory_profession_stage8_catalog;
 IF v_count<>72 THEN RAISE EXCEPTION 'expected_exactly_72_old_recipes_but_found_%',v_count; END IF;
 IF EXISTS(SELECT 1 FROM public.territory_profession_stage8_catalog WHERE id LIKE 'mw_%')
 THEN RAISE EXCEPTION 'masterworks_already_present_refusing_overwrite'; END IF;
 IF EXISTS(SELECT 1 FROM public.territory_profession_stage8_items WHERE recipe_id LIKE 'mw_%')
 THEN RAISE EXCEPTION 'unexpected_prior_masterwork_receipts'; END IF;
END
$guard$;

