-- Readiness is authenticated, constant-size and exposes NO player data.
-- SECURITY DEFINER is narrowly scoped because clients have no SELECT on the
-- server-authoritative catalog; do not grant catalog write/read to browsers.
CREATE OR REPLACE FUNCTION public.territory_profession_masterworks_ready()
RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO ''
AS $function$
DECLARE v_ready boolean;
BEGIN
  IF (SELECT auth.uid()) IS NULL THEN RETURN false; END IF;
  SELECT EXISTS(SELECT 1 FROM public.territory_profession_stage8_release
                WHERE id=1 AND enabled=true AND version='profession-stage8-draft-20261025-r2')
    AND (SELECT count(*)=25 FROM public.territory_profession_stage8_catalog WHERE id LIKE 'mw_%')
    AND (SELECT count(*)=97 FROM public.territory_profession_stage8_catalog)
  INTO v_ready;
  RETURN COALESCE(v_ready,false);
END
$function$;
REVOKE ALL ON FUNCTION public.territory_profession_masterworks_ready()
  FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.territory_profession_masterworks_ready()
  TO authenticated,service_role;

